shader_type canvas_item;

uniform float angle = 35.0;
uniform float thickness = 0.1;

void fragment() {
	vec2 p = UV * 2.0 - 1.0;
	p.y = -p.y;
	float m = tan(radians(angle));
	float offset = mix(-1.5, 1.5, fract(TIME * 0.5));
	float d = abs((p.y - m * p.x) / sqrt(1.0 + m * m) + offset);
	float band = step(d, thickness) * COLOR.a;
	COLOR.rgb = mix(COLOR.rgb, vec3(1.0), band);
}

shader_type canvas_item;

uniform float slope = 0.5;

void fragment() {
	vec2 p = UV * 2.0 - 1.0;
	p.y = -p.y;
	float v = p.y - slope * p.x;
	COLOR = vec4(0.65 + 0.2 * v, 0.65, 0.65 - 0.2 * v, 1.0);
}

